// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address originalOwner = c.owner();
        vm.prank(c.owner());
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        assertTrue(ok);
        if (originalOwner != newOwner) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == originalOwner);
        }
    }
}
